\documentclass{exam}
\usepackage{amsmath}
\usepackage{graphicx}
\usepackage{csvsimple}
\usepackage{siunitx}

\begin{document}

\begin{question}
Given the cubic equation $z^6+z^3+1=0$ has a complex root with an argument between $90$ and $180$ degrees, find this argument $\theta$, in degrees.

First, solve the equation to find the polar form of complex roots:

\begin{enumerate}
    \item All roots have the form $re^{i \theta}$ with $(r,\theta) \neq (0,0)$.
    \item The argument $\theta$ is the angle between the radial and the positive real axis.
    \item Use the complex cube root formula $z = r e^{\pm(i \theta/3)}$ for each root and remark that one root lies in the middle of the given interval, so $\theta \mod 180 = 120$.
    \item Recall that a factor $z-z_0$ corresponds to a root in the polar form $z_0$ and the $n$-th root $z^{1/n}$ corresponds to the factor $(z-z_0)^n$. Thus we get a factorization of the form $(z-z_1)(z-z_2)^2$ where $0 < \arg z_1 < 180$ and $\arg z_2 = \theta/3$ where $\theta \equiv 120 \ \text{mod} \ 180$.
    \item Solve for $z_1$ and $z_2$. Hint: since $z_2$ is a cube root and because of the given restriction of $\theta$, the result should coincide with $e^{\pm i\theta/3}$.
\end{enumerate}

\begin{parts}
\begin{part}
Write down possible values for $\theta$ that satisfy the given conditions. There should be two values.

\answer Choices: $\boxed{120}$ and $\boxed{360-120}$. Let's call them $\theta_1$ and $\theta_2.$ E.g., $\theta_1 = 120,\ \theta_2 = 360 - 120.$
\end{part}

\begin{part}Now verify which one of $\theta_1$ and $\theta_2$ satisfies the given conditions.

\begin{subparts}
\begin{subpart}
Let's find the polar form $z_1$ and $z_2$. For $z_1$ we can use the parameter $x= \cos \theta_k,\ y= \sin \theta_k$. Remember that $\theta_k \mod 180 = 120$ for $k=1,2$ and that $x^3 + y^3 -3xy(x^2+y^2) = x(1-x^2-y^2)^2 - y^3$ to form $z_1$.

\begin{align}
\theta_1 = 120&\text{ and } \theta_2 = 360 - 120 \nonumber \\
x_1 = \cos(120), \ y_1 = \sin(120)&\quad x_2 = \cos(360-120), \ y_2 =\sin(360-120) \nonumber \\
x_1 = -\frac12,& y_1 = -\frac{\sqrt3}{2} \quad x_2 = -\frac12, \ y_2 = \frac{\sqrt3}{2},\quad\;(\text{these are complex conjugates})\nonumber
\end{align}
Going back to the representation of the roots $z_1$ and $z_2$ in polar form use the identity $\cos(a) = \frac{e^{ia} + e^{-ia}}{2} $ and $\sin(a) = i(\frac{e^{ia} - e^{-ia}}{2})$, which will be used in the next step.

\answer There should be a rationalization of the roots form. E.g., $z_1 = -\frac{1}{2}-\frac{\sqrt3}{2}\cdot i$.
\end{subpart}

\begin{subpart}Now find the argument $\phi_i$ corresponding to $z_i$. We will use $\phi_i=\arg z_i= \tan^{-1}\left(\frac{y_i}{x_i}\right)$. Write down the polar form of each root $z_1$ and $z_2$ by its argument $\phi_1$ and $\phi_2$.

\answer Likely the result is more visually understandable in DMS format (e.g., $\phi_1 = 120^\circ$ and $\phi_2 = 240^\circ$).
\end{subpart}

\begin{subpart}
Finally, since $0 <  \phi_1 < 180$ and $180 <  \phi_2 < 360$, why does the correct answer to this question have to be $\boxed{120}$?

\answer $\theta$ has to be between 90 and 180. The only option that is between 90 and 180 degrees is 120.
\end{subpart}
\end{subparts}
\end{parts}

\boxed{120}
\end{question}

\end{document}

